"use client";
import { useEffect, useRef, useState } from 'react';
import './FeaturesSection.css';

const features = [
  {
    num: '01',
    title: 'AI Agent Enclaves',
    description:
      'Multi-agent models continuously evaluate risk and predict yield across major L2 protocols and DeFi pools without sharing proprietary strategies.',
  },
  {
    num: '02',
    title: 'TEE Validation',
    description:
      'Decisions are computed and validated inside a Trusted Execution Environment (Intel SGX) via Chainlink CRE, guaranteeing unbiased and tamper-proof off-chain consensus.',
  },
  {
    num: '03',
    title: 'Cross-chain Reallocation',
    description:
      'ArcMind calculates the marginal yield and automatically moves capital using CCTP if the yield differential overcomes cross-chain gas fees and slippage thresholds.',
  },
  {
    num: '04',
    title: 'Verifiable Execution',
    description:
      'Every autonomous decision made by the Orchestrator is hashed and attested on the 0G Chain Data Availability layer to ensure full transparency of agent actions.',
  },
];

export default function FeaturesSection() {
  const [activeIndex, setActiveIndex] = useState(0);
  const [progress, setProgress] = useState(25);
  const itemRefs = useRef<(HTMLLIElement | null)[]>([]);

  useEffect(() => {
    const observers: IntersectionObserver[] = [];

    itemRefs.current.forEach((el, i) => {
      if (!el) return;
      const obs = new IntersectionObserver(
        ([entry]) => {
          if (entry.isIntersecting) {
            setActiveIndex(i);
            setProgress(((i + 1) / features.length) * 100);
          }
        },
        { threshold: 0.35, rootMargin: '-5% 0px -45% 0px' }
      );
      obs.observe(el);
      observers.push(obs);
    });

    return () => observers.forEach(obs => obs.disconnect());
  }, []);

  return (
    <section className="features-section">
      {/* Sticky header */}
      <div className="features-header">
        <div className="features-progress-bar">
          <div className="features-progress-fill" style={{ width: `${progress}%` }} />
        </div>
        <div className="features-header-inner">
          <h2 className="features-header-title">
            How ArcMind Works<span className="features-header-dot">.</span>
          </h2>
          <div className="features-header-counter">
            {String(activeIndex + 1).padStart(2, '0')} / {String(features.length).padStart(2, '0')}
          </div>
        </div>
      </div>

      {/* Items */}
      <ul className="features-list">
        {features.map((f, i) => (
          <li
            key={f.num}
            ref={el => { itemRefs.current[i] = el; }}
            className={`features-item${i === activeIndex ? ' active' : ''}`}
          >
            <div className="features-item-inner">
              <div className="features-item-number">
                <span className={`features-num${i === activeIndex ? ' active' : ''}`}>
                  {f.num}.
                </span>
              </div>
              <div className="features-item-content">
                <h3 className={`features-item-title${i === activeIndex ? ' active' : ''}`}>
                  {f.title}
                </h3>
                <p className={`features-item-desc${i === activeIndex ? ' active' : ''}`}>
                  {f.description}
                </p>
              </div>
            </div>
          </li>
        ))}
      </ul>
    </section>
  );
}
